{
  "document_type": "tutorial",
  "primary_topic": "sensors_measurements",
  "main_subject": "фільтр Калмана",
  "purpose": "ознайомлення та демонстрація прикладу програмного алгоритму фільтра Калмана",
  "components": [
    {
      "name": "BMP280",
      "model": null,
      "manufacturer": null,
      "role": "датчик атмосферного тиску"
    }
  ],
  "technical_parameters": [
    {
      "subject": "коваріація помилки прогнозу",
      "name": "P",
      "value": "значення оновлюється після кожного кроку прогнозу",
      "unit": null
    },
    {
      "subject": "оцінка поточного стану системи",
      "name": "Xe",
      "value": "значення оновлюється на основі вимірювань та прогнозу",
      "unit": null
    },
    {
      "subject": "прогнозована коваріація помилки",
      "name": "Pc",
      "value": "використовується для подальшого оновлення значення P",
      "unit": null
    },
    {
      "subject": "коефіцієнт Калмана",
      "name": "G",
      "value": "визначає, як сильно враховується вимірювання в оновленні оцінки стану",
      "unit": null
    },
    {
      "subject": "прогнозоване вимірювання",
      "name": "Zp",
      "value": "використовується для порівняння з реальним вимірюванням",
      "unit": null
    },
    {
      "subject": "прогнозований стан системи",
      "name": "Xp",
      "value": "використовується для подальшого оновлення значення Xe",
      "unit": null
    },
    {
      "subject": "початкове значення вимірювання",
      "name": "initial_measurement",
      "value": "значення",
      "unit": null
    },
    {
      "subject": "швидкість реакції фільтра",
      "name": "reaction_speed",
      "value": "значення в діапазоні від 0.01 до 0.1",
      "unit": null
    },
    {
      "subject": "середнє відхилення",
      "name": "average_deviation",
      "value": "значення",
      "unit": null
    }
  ],
  "interfaces_protocols": [
    "Arduino",
    "Python"
  ],
  "software_tools": [
    "JupyterLab",
    "Anaconda"
  ]
}

